#include "BoundaryFill.h"
#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QDir>
#include <QJsonDocument>
#include <BRepClass3d_SolidClassifier.hxx>
#include <BRepGProp.hxx>
#include <GProp_GProps.hxx>
#include <iostream>
#include <cmath>
#include <stdexcept>
namespace {
void check(bool yes,const QString& text){if(!yes)throw std::runtime_error(text.toStdString());}
void commit(CadDocument& d,const QJsonObject& c,const QString& label){const auto e=d.commit(c,label);check(e.isEmpty(),label+": "+e+" "+QString::fromUtf8(QJsonDocument(d.lastEvaluationError()).toJson(QJsonDocument::Compact)));}
void append(CadDocument& d,const QJsonObject& f){auto c=d.authored();auto rows=c["features"].toArray();rows.append(f);c["features"]=rows;commit(d,c,"Add input sketch");}
QJsonArray tools(const CadDocument& d){QJsonArray refs;for(const auto& b:d.bodies())refs.append(QJsonObject{{"bodyId",b.bodyId},{"producerFeatureId",b.featureId}});return refs;}
QJsonObject draft(const CadDocument& d,const QString& owner){return {{"id",CadDocument::newId()},{"bodyId",CadDocument::newId()},{"type","boundaryFill"},{"ownerId",owner},{"name","Boundary Fill"},{"visible",true},{"parameters",QJsonObject{{"operation","newBody"},{"tools",tools(d)},{"removeTools",true}}}};}
QJsonObject arguments(const QJsonObject& f,const QJsonObject& cell){auto args=f["parameters"].toObject();args["cell"]=cell;args["newFeatureId"]=f["id"];args["newBodyId"]=f["bodyId"];args["ownerId"]=f["ownerId"];return args;}
QSet<QString> faceIds(const EvaluatedBody& b){QSet<QString> result;for(const auto& f:b.supportFaces)result.insert(f.faceId);return result;}
QSet<QString> edgeIds(const EvaluatedBody& b){QSet<QString> result;for(const auto& e:b.solidEdges)result.insert(e.edgeId);return result;}
void standalone(){
 CadDocument d;const auto owner=d.authored()["documentId"].toString();
 auto sheet=[&](const QString& plane,double x1,double y1,double x2,double y2){auto s=SketchGeometry::newFeature(owner,plane,"Box boundary");s=SketchGeometry::addLine(s,{{"u1Mm",x1},{"v1Mm",y1},{"u2Mm",x2},{"v2Mm",y2}});append(d,s);const auto eid=s["parameters"].toObject()["entities"].toArray()[0].toObject().value("id");commit(d,CadDocument::surfaceExtrudeCandidate(d.authored(),{{"sketchId",s["id"]},{"entityIds",QJsonArray{eid}},{"sideOneMm",10},{"sideTwoMm",10}}),"Box sheet");};
 sheet("XZ",-10,0,10,0);sheet("XZ",-10,20,10,20);sheet("XZ",-10,0,-10,20);sheet("XZ",10,0,10,20);sheet("YZ",-10,0,-10,20);sheet("YZ",10,0,10,20);
 const auto before=d.authored();const auto f=draft(d,owner);const auto partition=BoundaryFill::partition(f,d.evaluation());check(partition.cells.size()==1,"Six retained sheets make one actual cell");const auto& cell=partition.cells.front();check(std::abs(cell.summary["volumeMm3"].toDouble()-8000)<1e-5 && cell.supportFaces.size()==6 && cell.solidEdges.size()==12,"Exact valid box cell topology and volume");
 const auto pt=cell.selectionPointMm;check(pt.size()==3 && BRepClass3d_SolidClassifier(cell.shape,gp_Pnt(pt[0].toDouble(),pt[1].toDouble(),pt[2].toDouble()),1e-7).State()==TopAbs_IN,"Cell marker qualified by actual solid");
 auto sameTools=f;auto params=f["parameters"].toObject();auto refs=params["tools"].toArray();QJsonArray reversed;for(auto i=refs.size();i>0;--i)reversed.append(refs[i-1]);params["tools"]=reversed;sameTools["parameters"]=params;
 check(BoundaryFill::applyCell(QJsonObject{{"id",f["id"]},{"bodyId",f["bodyId"]},{"ownerId",owner},{"parameters",QJsonObject{{"tools",reversed},{"cell",cell.reference},{"removeTools",false}}}},partition).shape.IsSame(cell.shape),"Cheap selection accepts canonical tool order without rebuilding");
 auto args=arguments(f,cell.reference);args["removeTools"]=false;commit(d,CadDocument::boundaryFillCandidate(d.authored(),args),"Keep Boundary Fill tools");check(d.bodies().size()==7,"Keeper keeps six source tools");const auto first=d.bodies().back();check(faceIds(first).size()==6 && edgeIds(first).size()==12,"Named result topology");
 args.remove("newFeatureId");args.remove("newBodyId");args.remove("ownerId");args["featureId"]=f["id"];args["removeTools"]=true;commit(d,CadDocument::boundaryFillCandidate(d.authored(),args),"Consume Boundary Fill tools");const auto consumed=d.authored();check(d.bodies().size()==1 && d.bodies().back().bodyId==first.bodyId,"One new solid consumes evaluated tools only");d.history().undo();check(d.bodies().size()==7,"Undo consumption restores tools");d.history().redo();check(d.authored()==consumed && d.bodies().size()==1,"Redo consumption exact");
 auto edited=d.authored();auto rows=edited["features"].toArray();for(int i=0;i<rows.size();++i){auto s=rows[i].toObject();if(s["type"]!="sketch")continue;auto p=s["parameters"].toObject();auto points=p["points"].toArray();for(int j=0;j<points.size();++j){auto q=points[j].toObject();if(q["vMm"].toDouble()==20){q["vMm"]=22;points[j]=q;}}p["points"]=points;s["parameters"]=p;rows[i]=s;}edited["features"]=rows;commit(d,edited,"Raise source box boundaries");check(std::abs(d.bodies().back().summary["volumeMm3"].toDouble()-8800)<1e-5 && faceIds(d.bodies().back())==faceIds(first) && edgeIds(d.bodies().back())==edgeIds(first),"Actual source edit retains selected cell and face/edge identities");
 const auto final=d.authored();auto bad=args;auto cellRef=cell.reference;auto sources=cellRef["sourceFaces"].toArray();auto lost=sources[0].toObject();lost["faceId"]=CadDocument::newId();sources[0]=lost;cellRef["sourceFaces"]=sources;bad["cell"]=cellRef;check(!d.commit(CadDocument::boundaryFillCandidate(final,bad),"Unavailable cell").isEmpty() && d.authored()==final,"Missing cell refuses atomically");
 auto duplicates=partition;duplicates.cells.push_back(partition.cells.front());bool rejected=false;try{auto selected=f;auto p=selected["parameters"].toObject();p["cell"]=cell.reference;selected["parameters"]=p;BoundaryFill::applyCell(selected,duplicates);}catch(const GeometryKernel::EvaluationError& e){rejected=e.diagnostics()["code"]=="boundary_fill_cell_ambiguous";}check(rejected,"Ambiguous selected cell refuses");
 auto missing=args;auto missingTools=missing["tools"].toArray();auto missingRef=missingTools[0].toObject();missingRef["bodyId"]=CadDocument::newId();missingTools[0]=missingRef;missing["tools"]=missingTools;check(!d.commit(CadDocument::boundaryFillCandidate(final,missing),"Missing tool").isEmpty() && d.authored()==final,"Missing tool atomic");
 QTemporaryDir temp;check(d.save(temp.filePath("boundary-fill.alloy")).isEmpty(),"Save retained fill");CadDocument reopen;check(reopen.open(temp.filePath("boundary-fill.alloy")).isEmpty() && reopen.authored()==final && faceIds(reopen.bodies().back())==faceIds(first),"Retained fill exact reopen");
 auto afterRemove=CadDocument::removeBodyCandidate(final,{{"bodyId",refs[0].toObject()["bodyId"]},{"ownerId",owner}});check(!d.commit(afterRemove,"Remove consumed tool").isEmpty() && d.authored()==final,"Consumed tool unavailable downstream");
 // Actual duplicate coplanar tool ancestry is ambiguous, even though all inputs are valid sheets.
 CadDocument ambiguous;check(ambiguous.recover(before).isEmpty(),"Restore source sheets for ambiguity gate");const auto firstSketch=before["features"].toArray()[0].toObject();const auto sourceEntity=firstSketch["parameters"].toObject()["entities"].toArray()[0].toObject().value("id");commit(ambiguous,CadDocument::surfaceExtrudeCandidate(ambiguous.authored(),{{"sketchId",firstSketch["id"]},{"entityIds",QJsonArray{sourceEntity}},{"sideOneMm",10},{"sideTwoMm",10}}),"Duplicate exact bottom sheet");rejected=false;try{BoundaryFill::partition(draft(ambiguous,owner),ambiguous.evaluation());}catch(const GeometryKernel::EvaluationError& e){rejected=e.diagnostics()["code"]=="boundary_fill_face_ambiguous";}check(rejected,"Duplicate source contributors refuse exact face naming");
 std::cout<<"BOUNDARY_FILL_CORE_OK exactCell keeperConsumer sourceEdit stableFacesEdges marker ambiguity missing atomic history reopen\n";
}
void iron(const QString& source,const QString& out){
 CadDocument d;check(d.open(source).isEmpty(),"Open independently qualified contact fixture");check(d.bodies().size()==5,"Actual five tools");const auto owner=d.bodies().front().ownerId;auto f=draft(d,owner);const auto partition=BoundaryFill::partition(f,d.evaluation());check(partition.cells.size()==1,"Actual unique iron cell");const auto initialCell=partition.cells.front();check(initialCell.supportFaces.size()==7 && std::abs(initialCell.summary["volumeMm3"].toDouble()-98122.00205271378)<.01,"Actual qualified positive-volume iron");check(partition.diagnostics["effectiveFuzzyValue"].toDouble()==1e-7 && !partition.diagnostics["warnings"].toString().isEmpty(),"Preserve default tolerance and tip diagnostics");
 commit(d,CadDocument::boundaryFillCandidate(d.authored(),arguments(f,initialCell.reference)),"Retained iron Boundary Fill");check(d.bodies().size()==1 && d.bodies().back().ownerId==owner && d.bodies().back().summary["type"]=="solid","Same-owner new solid consumes source sheets");const auto initial=d.authored();const auto solid=d.bodies().back();
 // A modest upper profile source edit retains the exact lower/bottom contact.
 auto edited=initial;auto rows=edited["features"].toArray();bool moved=false;for(int i=0;i<rows.size();++i){auto s=rows[i].toObject();if(s["name"]!="Back and notch sheets")continue;auto p=s["parameters"].toObject();const auto upper=p["entities"].toArray()[0].toObject();const auto mid=upper.value("pointIds").toArray().at(1);auto points=p["points"].toArray();for(int j=0;j<points.size();++j)if(points[j].toObject()["id"]==mid){auto q=points[j].toObject();q["vMm"]=q["vMm"].toDouble()+1;points[j]=q;moved=true;}p["points"]=points;s["parameters"]=p;rows[i]=s;}check(moved,"Find actual retained upper fit point");edited["features"]=rows;commit(d,edited,"Edit upper crossing sheet");check(faceIds(d.bodies().back())==faceIds(solid) && edgeIds(d.bodies().back())==edgeIds(solid) && std::abs(d.bodies().back().summary["volumeMm3"].toDouble()-solid.summary["volumeMm3"].toDouble())>1,"Actual source volume edit preserves cell/face/edge identities");
 const auto final=d.authored();d.history().undo();check(d.authored()==initial,"Actual source undo");d.history().redo();check(d.authored()==final,"Actual source redo");QDir().mkpath(out);check(d.save(out+"/retained-iron-boundary-fill.alloy").isEmpty(),"Save actual retained solid");CadDocument reopen;check(reopen.open(out+"/retained-iron-boundary-fill.alloy").isEmpty() && reopen.authored()==final && faceIds(reopen.bodies().back())==faceIds(solid),"Actual fill exact reopen");
 std::cout<<"BOUNDARY_FILL_IRON_OK cell="<<initialCell.cellId.toStdString()<<" volume="<<solid.summary["volumeMm3"].toDouble()<<" faces="<<solid.supportFaces.size()<<" owner sourceEdit stableCellFacesEdges history reopen\n";
}
}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{if(argc<4 || QString::fromLocal8Bit(argv[3])!="iron-only")standalone();if(argc>2)iron(QString::fromLocal8Bit(argv[1]),QString::fromLocal8Bit(argv[2]));return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
